// Exact port of the pinned JS edge stamper. No fast-math. Rays and
// angle lookup are generated by the caller's JS Math implementation so the
// current renderer's floating-point decisions remain the reference.
#include <stdint.h>
#define SIDE 640
#define PIXELS (SIDE*SIDE)
#define MATERIALS 1024
#define ENTRIES 256
#define IMAGES 512
#define IMAGE_INDICES 4096
static int32_t mt[MATERIALS*3],et[ENTRIES*7],images[IMAGES*7],indices[IMAGE_INDICES];
static double percent[ENTRIES],rayX[16],rayY[16],angles[65536];
static uint32_t atlas[262144],rgba[PIXELS];
static int16_t mat[PIXELS],sceneMat[PIXELS];
static uint8_t painted[PIXELS],sceneArt[PIXELS],seamSkip[16];
// One list: generation appends at front; seam appends backward from end.
// Reverse seam iteration restores the exact original y/x scan order.
static int32_t candidates[PIXELS],localX[SIDE],localY[SIDE];
static int16_t sampleX[SIDE*64],sampleY[SIDE*64];
static int preparedX=0,preparedY=0;
static int W,H,OX,OY,SX,SY,X0,X1,Y0,Y1,NM,NE,NI,AW,REACH,chunkX0,chunkY0;
static uint32_t SEED;
#define MAX(a,b) ((a)>(b)?(a):(b))
#define MIN(a,b) ((a)<(b)?(a):(b))
int abi_version(void){return 1;}
uint32_t buffer_ptr(int n){
 switch(n){case 0:return(uint32_t)(uintptr_t)mt;case 1:return(uint32_t)(uintptr_t)et;
 case 2:return(uint32_t)(uintptr_t)percent;case 3:return(uint32_t)(uintptr_t)indices;
 case 4:return(uint32_t)(uintptr_t)images;case 5:return(uint32_t)(uintptr_t)rayX;
 case 6:return(uint32_t)(uintptr_t)rayY;case 7:return(uint32_t)(uintptr_t)angles;
 case 8:return(uint32_t)(uintptr_t)atlas;case 9:return(uint32_t)(uintptr_t)mat;
 case 10:return(uint32_t)(uintptr_t)rgba;case 11:return(uint32_t)(uintptr_t)sceneMat;
 case 12:return(uint32_t)(uintptr_t)sceneArt;case 13:return(uint32_t)(uintptr_t)seamSkip;default:return 0;}
}
int configure(int nm,int ne,int ni,int aw,int reach){
 if(nm<1||nm>MATERIALS||ne<0||ne>ENTRIES||ni<0||ni>IMAGES||aw<1||reach<0)return 0;
 NM=nm;NE=ne;NI=ni;AW=aw;REACH=reach;preparedX=preparedY=0;return 1;
}
static int mod(int a,int b){int r=a%b;return r<0?r+b:r;}
static int floor512(int v){return v>=0?v/512:-((-(int64_t)v+511)/512);}
static int hasEntries(int id){return id>0&&id<NM&&mt[id*3+1]>0;}
static int typeOf(int id){return id>0&&id<NM?mt[id*3+2]:-9999;}
static uint32_t hash32(int x,int y,uint32_t seed,int entry,int draw){
 uint32_t h=(uint32_t)x*0x27d4eb2du^(uint32_t)y*0x165667b1u^seed*0x9e3779b1u^(uint32_t)(entry*8+draw)*0x85ebca6bu;
 h=(h^(h>>16))*0x85ebca6bu;h=(h^(h>>13))*0xc2b2ae35u;return h^(h>>16);
}
static double normalAngle(int cx,int cy,int id,int type,int sameType){
 uint32_t mask=0;
 for(int ray=0;ray<16;ray++){
  int last=-1;
  for(int t=1;t<5;t++){
   // Do not substitute cx+__builtin_floor(dx*t): cardinal floating residuals differ.
   int x=sampleX[cx*64+ray*4+t-1],y=sampleY[cy*64+ray*4+t-1];
   if(x<0||y<0||x>=W||y>=H)break;
   int j=y*W+x;if(j==last)continue;last=j;
   int m=mat[j];if(m==id||(sameType&&m>0&&typeOf(m)==type))continue;
   mask|=1u<<ray;break;
  }
 }
 return angles[mask];
}
static double cardinal(const uint8_t *mask,int bit,int count){
 if(count>7)return 0;
 if((mask[0]>>bit&1)&&(mask[3]>>bit&1)&&(mask[6]>>bit&1))return 180;
 if((mask[0]>>bit&1)&&(mask[1]>>bit&1)&&(mask[2]>>bit&1))return 270;
 if((mask[6]>>bit&1)&&(mask[7]>>bit&1)&&(mask[8]>>bit&1))return 90;
 return 0;
}
static int chooseImage(const int32_t *entry,double angle,uint32_t start){
 int count=entry[6];for(int k=0;k<count;k++){
  int image=indices[entry[5]+(start+(uint32_t)k)%(uint32_t)count];
  const int32_t *im=images+image*7;if(angle>=im[4]&&angle<im[5])return image;
 }return -1;
}
static void blit(int cx,int cy,int id,int overwrite,int image,int flip,int transpose,int clip,int chunkX,int chunkY){
 const int32_t *im=images+image*7;int ax=im[0],ay=im[1],iw=im[2],ih=im[3],flags=im[6];
 int minX=0,minY=0,maxX=W-1,maxY=H-1;
 if(clip){minX=MAX(minX,chunkX);maxX=MIN(maxX,chunkX+511);minY=MAX(minY,chunkY);maxY=MIN(maxY,chunkY+511);}
 int ox,oy,w,h,fixX=-1,fixY=-1;
 if(flags&2){ox=cx;oy=cy-ih/2;w=1;h=ih;fixX=mod(OX+cx,iw);transpose=0;}
 else if(flags&4){ox=cx-iw/2;oy=cy;w=iw;h=1;fixY=mod(OY+cy,ih);transpose=0;}
 else if(transpose){ox=cx-ih/2;oy=cy-iw/2;w=ih;h=iw;}
 else {ox=cx-iw/2;oy=cy-ih/2;w=iw;h=ih;}
 int x0=MAX(ox,minX),x1=MIN(ox+w-1,maxX),y0=MAX(oy,minY),y1=MIN(oy+h-1,maxY);
 for(int y=y0;y<=y1;y++)for(int x=x0;x<=x1;x++){
  int d=y*W+x;if(mat[d]!=id||(!overwrite&&painted[d]))continue;
  int sx,sy;if(transpose){sx=y-oy;sy=x-ox;}else{sx=fixX>=0?fixX:x-ox;sy=fixY>=0?fixY:y-oy;}
  int fx=flip&1?iw-1-sx:sx,fy=flip&2?ih-1-sy:sy;
  uint32_t word=atlas[(ay+fy)*AW+ax+fx];
  // A transparent colored texel still consumes the first-painted flag.
  if(!word)continue;rgba[d]=word;painted[d]=1;
 }
}
static int interior(int i,int id){
 int same=(mat[i-1]==id)+(mat[i+1]==id)+(mat[i-W]==id)+(mat[i+W]==id)
  +(mat[i-W-1]==id)+(mat[i-W+1]==id)+(mat[i+W-1]==id)+(mat[i+W+1]==id);
 return same>=7;
}
static void stampCell(int x,int y,uint32_t seed,int clip){
 int i=y*W+x,id=mat[i],type=typeOf(id),sameMat=0,sameType=0;uint8_t mask[9];
 for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){
  int m=mat[i+dy*W+dx],k=(dy+1)*3+dx+1;
  if(m==id){sameMat++;sameType++;mask[k]=3;}
  else if(m>0&&typeOf(m)==type){sameType++;mask[k]=1;}else mask[k]=0;
 }
 int first=mt[id*3],count=mt[id*3+1],wx=OX+x,wy=OY+y;
 for(int e=0;e<count;e++){
  const int32_t *entry=et+(first+e)*7;int kind=entry[0],overwrite=entry[1],reqMat=entry[2],reqType=entry[3];
  if((double)hash32(wx,wy,seed,e,0)/4294967296.0>percent[first+e])continue;
  if(kind!=3&&(reqMat||reqType)){
   int bit=reqMat?1:0,sum=(mask[1]>>bit&1)+(mask[3]>>bit&1)+(mask[5]>>bit&1)+(mask[7]>>bit&1);
   if(sum!=2&&sum!=3)continue;
  }
  int image=-1;double angle=0;
  if(kind==1){int n=entry[6];image=indices[entry[5]+MIN(n-1,(int)((double)hash32(wx,wy,seed,e,1)/4294967296.0*n))];}
  else if(kind==2||kind==3){
   angle=kind==3?normalAngle(x,y,id,type,!!reqType):reqMat?cardinal(mask,1,sameMat):cardinal(mask,0,sameType);
   if(angle<0)continue;image=chooseImage(entry,angle,hash32(wx,wy,seed,e,1)%(uint32_t)entry[6]);if(image<0)continue;
  }else if(kind==0){
   uint32_t c=(uint32_t)entry[4];if(!(c>>24)||(!overwrite&&painted[i]))continue;
   rgba[i]=(c&0xff000000u)|((c>>16)&255)|((c>>8)&255)<<8|(c&255)<<16;painted[i]=1;continue;
  }else continue;
  int cx=x,cy=y,flags=images[image*7+6];
  if(kind!=1&&(flags&6)){if(angle>=135&&angle<225)cx++;else if(angle>=225&&angle<315)cy++;}
  int flip=0,transpose=0;
  if(flags&1){if(hash32(wx,wy,seed,e,2)>0x80000000u)flip|=1;if(hash32(wx,wy,seed,e,3)>0x80000000u)flip|=2;transpose=hash32(wx,wy,seed,e,4)>0x80000000u;}
  blit(cx,cy,id,overwrite,image,flip,transpose,clip,x-localX[x],y-localY[y]);
 }
}
int start(int w,int h,int ox,int oy,uint32_t seed,int shiftX,int shiftY,int inset){
 if(w<1||h<1||w>SIDE||h>SIDE||!NM)return 0;
 if(preparedX<w){for(int c=preparedX;c<w;c++)for(int ray=0;ray<16;ray++)for(int t=1;t<5;t++)
  sampleX[c*64+ray*4+t-1]=(int16_t)__builtin_floor((double)c+(rayX[ray]/5.0)*(double)t);preparedX=w;}
 if(preparedY<h){for(int c=preparedY;c<h;c++)for(int ray=0;ray<16;ray++)for(int t=1;t<5;t++)
  sampleY[c*64+ray*4+t-1]=(int16_t)__builtin_floor((double)c+(rayY[ray]/5.0)*(double)t);preparedY=h;}
 W=w;H=h;OX=ox;OY=oy;SEED=seed;SX=shiftX;SY=shiftY;
 __builtin_memset(rgba,0,(uint32_t)w*h*4);__builtin_memset(painted,0,(uint32_t)w*h);
 int margin=MAX(1,inset-REACH);X0=margin;Y0=margin;X1=MAX(margin,w-margin);Y1=MAX(margin,h-margin);
 chunkX0=floor512(OX+SX);chunkY0=floor512(OY+SY);
 for(int x=0;x<W;x++)localX[x]=mod(OX+x+SX,512);
 for(int y=0;y<H;y++)localY[y]=mod(OY+y+SY,512);
 int nGen=0,nSeam=0,capacity=(X1-X0)*(Y1-Y0);
 for(int y=Y0;y<Y1;y++)for(int x=X0;x<X1;x++){
  int i=y*W+x,id=mat[i];if(!hasEntries(id)||interior(i,id))continue;
  int lx=localX[x],ly=localY[y];
  if(lx<8||lx>=504||ly<8||ly>=504)candidates[capacity-1-nSeam++]=i;else candidates[nGen++]=i;
 }
 for(int n=0;n<nGen;n++){int i=candidates[n],y=i/W,x=i-y*W;stampCell(x,y,SEED,1);}
 for(int n=0;n<nSeam;n++){
  int i=candidates[capacity-1-n],y=i/W,x=i-y*W;
  int gx=floor512(OX+x+SX)-chunkX0,gy=floor512(OY+y+SY)-chunkY0;
  if(seamSkip[gy*4+gx])continue;stampCell(x,y,SEED,0);
 }
 return 1;
}
// JS copies only the intersection into sceneMat/sceneArt. Original scene bounds
// remain explicit for the inset scan; edge eligibility is whole-scene state.
int scene(int sceneX,int sceneY,int sw,int sh,int clipX,int clipY,int cw,int ch,int eligible){
 if(cw<0||ch<0||cw>SIDE||ch>SIDE)return 0;
 int bx=sceneX-OX,by=sceneY-OY;
 for(int y=0;y<ch;y++)for(int x=0;x<cw;x++){
  int s=y*cw+x,v=sceneMat[s];if(v==-2)continue;
  int i=(clipY+y)*W+clipX+x;mat[i]=v;painted[i]=(v>0&&sceneArt[s])?1:0;rgba[i]=0;
 }
 if(!eligible)return 1;
 int sy0=MAX(1,Y0-by),sy1=MIN(sh-1,Y1-by),sx0=MAX(1,X0-bx),sx1=MIN(sw-1,X1-bx);
 for(int ly=sy0;ly<sy1;ly++)for(int lx=sx0;lx<sx1;lx++){
  int x=bx+lx,y=by+ly,i=y*W+x,id=mat[i];if(!hasEntries(id)||interior(i,id))continue;
  stampCell(x,y,SEED^0x53434e45u,0);
 }
 return 1;
}
